def coal_material_efs(comp):
    """燃煤物料衡算: 返回 dict(pollutant -> (EF g/kg, ok, need))
    SO2 不依赖燃烧技术(sr=0.15 对工业源各技术相同); PM/BC/OC 依赖燃烧技术"""
    out = {}
    s = comp.get("sulfur")
    if s is not None:
        out["SO2"] = (2.0 * s * (1.0 - 0.15), True, None)
    else:
        out["SO2"] = (None, False, "MISSING_SULFUR")
    tech = comp.get("tech")
    if tech is None:
        return out
    _, ar = C1[tech]
    f25, f10 = C2[tech]
    fb, fo = C3[tech]
    ash = comp.get("ash")
    if ash is not None:
        pm25 = ash * (1.0 - ar) * f25
        pm10 = ash * (1.0 - ar) * f10
        out["PM2.5"] = (pm25, True, None)
        out["PM10"] = (pm10, True, None)
        out["BC"] = (pm25 * fb, True, None)
        out["OC"] = (pm25 * fo, True, None)
    else:
        for p in ("PM2.5", "PM10", "BC", "OC"):
            out[p] = (None, False, "MISSING_ASH")
